import Foundation

@main struct W007BudgetProbe {
    static func main() {
        var cases = 0
        let origins: [CGFloat] = [-.greatestFiniteMagnitude, -1e308, -1e100, -10000, -1000, -1, 0, 1, 10, 50, 100, 10000, 1e100, 1e308, .greatestFiniteMagnitude, .nan, .infinity, -.infinity]
        let heights: [CGFloat] = [-1, 0, .leastNonzeroMagnitude, 1e-300, 1, 47, 48, 100, 600, 1e100, 1e308, .infinity, .nan]
        let normalViewport = CGRect(x: 0, y: 100, width: 390, height: 600)
        for y in origins {
            for height in heights {
                let target = CGRect(x: 20, y: y, width: 100, height: height)
                let budget = StudioScrollTravelBudget.maximumDrags(target: target, viewport: normalViewport)
                precondition(budget == 0 || (12...64).contains(budget), "target boundary produced \(budget)")
                cases += 1
            }
        }
        let normalTarget = CGRect(x: 20, y: -5000, width: 100, height: 44)
        for y in origins {
            for height in heights {
                let viewport = CGRect(x: 0, y: y, width: 390, height: height)
                let budget = StudioScrollTravelBudget.maximumDrags(target: normalTarget, viewport: viewport)
                precondition(budget == 0 || (12...64).contains(budget), "viewport boundary produced \(budget)")
                cases += 1
            }
        }
        for distance in stride(from: 0.0, through: 30000.0, by: 37.0) {
            let above = CGRect(x: 20, y: 400 - distance - 22, width: 100, height: 44)
            let below = CGRect(x: 20, y: 400 + distance - 22, width: 100, height: 44)
            precondition(StudioScrollTravelBudget.maximumDrags(target: above, viewport: normalViewport) == StudioScrollTravelBudget.maximumDrags(target: below, viewport: normalViewport), "asymmetric travel")
            cases += 1
        }
        let viewport = CGRect(x: 0, y: 116, width: 402, height: 597.333333333333)
        let captured = CGRect(x: 30, y: -4583, width: 212, height: 62)
        let capturedBudget = StudioScrollTravelBudget.maximumDrags(target: captured, viewport: viewport)
        precondition(capturedBudget == 25)
        precondition(StudioScrollTravelBudget.maximumDrags(target: CGRect(x: 20, y: 1e308, width: 100, height: 44), viewport: CGRect(x: 0, y: -1e308, width: 390, height: 600)) == 64)
        cases += 2
        print("W007 passed \(cases) actual-source numeric/symmetry checks; captured budget=\(capturedBudget); no Apple/UI execution.")
    }
}
